def search_algorithm(src, dsts, G, num_partitions):
    """Build the cheaper of independent shortest routes and a shared broadcast tree.

    The shared-tree candidate attaches each remaining destination through the
    lowest incremental-cost route from an already reached node.  Each output
    destination still receives a complete src-to-dst path, while common prefix
    links can be reused by broadcast-aware cost evaluators.  The independent
    shortest-path union is retained as a safe fallback when it has a lower
    unique-link cost.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    h.remove_edges_from([
        (u, v) for u, v, data in h.edges(data=True)
        if data.get("cost") is None
    ])

    unique_dsts = list(dict.fromkeys(dst for dst in dsts if dst != src))
    direct_paths = {}
    for dst in unique_dsts:
        direct_paths[dst] = nx.dijkstra_path(h, src, dst, weight="cost")

    def union_cost(paths):
        used_edges = set()
        total = 0.0
        for path in paths.values():
            for u, v in zip(path, path[1:]):
                if (u, v) not in used_edges:
                    used_edges.add((u, v))
                    total += float(h[u][v]["cost"])
        return total

    # Grow an arborescence.  The path selected at each step is charged only for
    # links that are not already present in the broadcast tree.
    pending = set(unique_dsts)
    tree_nodes = {src}
    tree_edges = set()
    root_paths = {src: [src]}

    while pending:
        best = None
        for start in list(tree_nodes):
            lengths, paths = nx.single_source_dijkstra(h, start, weight="cost")
            for dst in pending:
                if dst not in paths:
                    continue
                tail = paths[dst]
                incremental = sum(
                    float(h[u][v]["cost"])
                    for u, v in zip(tail, tail[1:])
                    if (u, v) not in tree_edges
                )
                candidate = (incremental, lengths[dst], start, dst, tail)
                if best is None or candidate[:2] < best[:2]:
                    best = candidate

        # All destinations were reachable in direct_paths, so this only guards
        # against malformed/disconnected graphs without returning partial paths.
        if best is None:
            root_paths = direct_paths
